#!/usr/bin/env python3
# reserve_L13a.py — 새 과 L13a(성 방어전 한눈에 · 세계 s13 의 a) — 면역 세계 「성 방어전」의 첫 장
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-14 새 과 L13a]'
new = {
 '회색 돌 성벽(성가퀴) · 무너진 틈 — 성 안에서 본 성': f'몸의 첫 장벽(피부 · 점막) · 무너진 틈 = 장벽을 넘은 자리 전용 {B} — 면역 세계 s13 「성 방어전」의 틀(L13a s1 · s2). 성 = 몸 · 안뜰 = 조직 · 그림은 성 안에서 본다(성벽이 위쪽 띠). 성벽 · 틈 · 하늘은 PIL(`L13a_pil.py`) — 다음 과도 같은 함수로 같은 성벽을 그린다. ⚠ 붉은 벽돌 담(= 막 · 핵막)과 재료로 가른다 — 회색 돌 + 성가퀴. ⚠ 틈 너머에 언덕을 그리면 망토 뒤에 낀 「초록 네모」로 읽혔다(일치 검사 1회) — 하늘만.',
 '붉은 리본 배지(로제트 — 둥근 붉은 꽃 + 금빛 가운데 + 리본 꼬리 둘)': f'자기(self)의 표지 전용 {B} — L13a s1. 성 안의 것은 모두 단다(주민 셋 · 흰 옷 넷 · 발코니의 병정 둘과 벌 · 잠옷 병정 · 둥근 흰 덩이) · 침입자(망토 두른 이 · 초록 세균)에게만 없다 = 비자기. 옛 s13p03 「전원이 단 둥근 배지」(= MHC I — 모든 유핵세포)를 이었다 — L13c 에서 이 배지가 그대로 MHC I 이 된다(NK 궁수는 배지 없는 자만 쏜다). PIL `badge()`. ⚠ 주민만 달면 「배지 없는 경비 · 병정 = 비자기」로 읽힌다 → 성 안 모두에게 단다(옛 판 logic_0929 가 고친 바로 그 자리). ⚠ 【큰 세균이 치켜든 빨간 리본 맨 부엌칼 …】(L12g — 리본 = 건넴)과 가른다 — 가슴에 단 꽃 꼴 배지. ⚠ 배지(badge)와 배지(培地 — 【갈색 약병을 얹은 파란 물총 … 이젤의 둥근 배지 둘】)는 소리만 같다.',
 '망토 두른 사람 + 품에 안은 흰 종이 두루마리': f'바이러스(단백질 껍질 + 핵산) 전용 {B} — L03b(청록 망토 · 두루마리를 두 손에) · L13a s1(보라 두건 망토 · 끈으로 묶은 두루마리 둘을 안고 성벽 틈으로 든다 — 두건 속은 어둡고 눈만 빛난다 · 배지 없음). 망토 = 껍질(캡시드) · 흰 종이 두루마리 = 핵산(종이 = RNA 문법 · L01). ⚠ 【체에 감긴 쇠사슬의 검은 자물쇠 + 먼지 망토 나그네의 큰 열쇠】(알도스테론)와 가른다 — 나그네는 열쇠를 들고 두루마리가 없다. ⚠ 두루마리를 묶은 끈은 갈색 — Gemini 의 빨간 리본은 갈색으로 칠했다(빨간 리본 = 건넴). ⚠ 보라 망토는 사람의 옷이다 — 【보라 리보솜】(보라 덩이 · 정거장)과 꼴로 갈린다.',
 '톨게이트 초소(칠하지 않은 민 나무 가로대) + 곁 게시판의 수배 전단': f'TLR(톨유사수용체) · PAMP(병원체 공통분자 패턴) 전용 {B} — L13a s5. 톨게이트의 톨 = Toll · 초소 창구의 흰 옷 경비 = TLR 을 지닌 선천 면역세포 · 전단에는 한 놈의 얼굴이 아니라 침입자 무리가 두루 지닌 무늬(= PAMP — 잠옷 병정의 종이에 그린 한 놈의 얼굴 = 항원결정부위와 견준다). 가로대는 초소 옆구리에서 틈 앞을 끝까지 가로지른다(늘인 것은 PIL `stretch_bar()` — 틈 가장자리에 못 미치면 「틈을 막지 않는다」로 읽혔다 · 일치 검사 1 · 2 · 9회). ⚠ 빨강 하양 줄무늬 차단기는 L12f(식욕)의 것 — 민 나무. ⚠ 통행료 동전을 그리지 않는다(동전 = ATP).',
 '수배 전단 셋 — 점선 알약 밑의 굵은 초록 꼬리 / 꽃을 금지 표지로 지운 금빛 꼰 밧줄 토막 / 끈으로 묶은 흰 두루마리 둘': f'TLR 이 보는 신호 셋 — 세균 플라젤린 · 비메틸화 CpG DNA · 바이러스 dsRNA 전용 {B} — L13a s6. 꼬리 = 편모(플라젤린) · 금빛 꼰 밧줄 = DNA(L01 항구의 밧줄) · 꽃 = 메틸기(【꽃 도장】) — 꽃을 금지 표지로 지움 = 메틸기 없음 · 흰 종이 두루마리 = RNA · 둘을 한데 묶음 = 이중가닥. 전단마다 같은 것을 마당의 침입자가 지녔다(꼬리 = 세균 둘 · 밧줄 = 오른쪽 세균이 쥐고 끎 · 두루마리 = 망토 두른 이). 전단 그림은 Gemini 조각(F1 · P1) · 게시판은 PIL. ⚠ 꼬리만 그린 전단은 「초록 뱀 · 벌레」로 읽혔다(일치 검사 1회) → 알약 몸을 점선으로만 그리고 꼬리를 굵게(「꼬리를 보라」).',
 '주둥이를 끈으로 묶은 삼베 자루의 네모 창 안에 앉은 흰 옷 경비': f'소낭(엔도솜) 안의 TLR = 안으로 들인 핵산(바이러스 dsRNA · CpG DNA)을 본다 전용 {B} — L13a s7(곁 게시판에 밧줄 · 두루마리 전단). 짝 = 성벽 앞 나무 초소(곁 게시판에 꼬리 전단) = 세포 표면 TLR(세균 겉 성분 — 플라젤린 · LPS). 핵산은 침입자의 몸 안에 있어 삼켜 자루(소낭) 안에서 껍질이 벗겨져야 드러난다. 자루 = 囊(주머니) — 【천 울타리가 뻗은 천 팔 둘 + … 공 담은 천 자루】(식포)와 같은 「삼킨 것을 담는 주머니」. ⚠ 【주둥이를 밧줄로 묶은 자루 모양 집 · 창 안의 포자】(자낭균)와 창 안의 것(포자 / 흰 옷 경비)으로 가른다 · 【사람이 멘 자루 개수】(배수성)와 다르다 — 땅에 선 사람 키만 한 자루.',
 '잠옷 · 수면 모자 차림으로 장화를 한 짝만 신은 장난감 병정(하품 · 세균 한 놈을 그린 종이 · 팔에 안은 두꺼운 빨간 책 · 발치의 털모자와 장화 한 짝)': f'적응 면역 = 처음엔 느림 · 특이적 · 기억 강함 전용 {B} — L13a s4(내성 문간 돌계단). 짝 = 벌써 파리채를 치켜들고 달려드는 흰 옷 경비 = 선천 면역(빠름 · 아무나 · 수첩 없음). 잠옷 바람 · 못 신은 장화 · 못 쓴 털모자 = 채비에 며칠(1차 반응) · 종이의 세균 한 놈 = 특이성(항원결정부위) · 두꺼운 빨간 책 = 기억(수첩). 종이 속 세균은 마당 세균 조각을 PIL 이 줄여 붙였다 · 털모자 · 장화는 Gemini 조각(A3). ⚠ 털모자를 PIL 로 민 통처럼 그리면 「양동이 · 종 · 돔」으로 읽혔다(일치 검사 1 ~ 5회) → 털 질감 · 금빛 턱끈 있는 조각으로. ⚠ 장화를 눕히면 「각진 검은 덩어리」 — 세운다. ⚠ 코 방울을 그리지 않는다(【구슬 기둥 꼭대기에서 코 방울을 불며 조는 제복 징수원 …】 = 수동수송).',
 '흰 옷 궁수(긴 활을 세워 쥐고 한 손을 이마에 대고 살핌 · 등에 화살통)': f'NK 세포(자연살해세포) 전용 {B} — L13a s2(선천 방어 다섯의 하나 — 활을 쥐고 성 안을 살핀다) · L13c 에서 배지(MHC I) 없는 자만 쏜다(missing-self — 옛 s13p03#4). 【흰 옷 경비】(백혈구)의 하나. ⚠ 시위를 당겨 누군가를 겨눈 궁수는 「겨눈 쪽을 쏜다」로 읽힌다(일치 검사 1회 — NK 는 세균을 쏘지 않는다) → 쏠 것이 없을 때는 활을 세워 쥔 망보는 자세. ⚠ 초록 옷 · 깃 모자의 옛 궁수는 알려진 옛이야기 인물을 닮아 흰 옷으로.',
 '돌로 두른 도랑 끝을 막은 나무 판자 보(洑) + 넘쳐 고인 물': f'보체 전용 {B} — L13a s2(보에 고인 물 = 보체 · 피에 녹아 흐르는 단백질). L13b 에서 도랑 셋 → 저수지(보) → 물줄기가 침입자의 몸에 구멍(MAC · 옛 s13p03#0 · #1). ⚠ 구멍은 침입자의 몸에 뚫는다 — 옛 판은 성벽(제 몸)에 뚫어 뜻이 어긋났다.',
 '집 벽에 걸린 회색 인터폰(수화기 · 꼬불꼬불한 줄)': f'인터페론 전용 {B} — L13a s2 · L13b(바이러스가 든 집이 이웃 집에 알린다 → 이웃이 항바이러스 단백질을 미리 갖춤). 인터폰 = 인터페론(소리). ⚠ 인터폰 판의 둥근 단추 열여섯(넷씩 네 줄)을 판 빛으로 덮었다 — 단추의 줄과 개수는 CD4 · CD8 예약(【조끼 단추의 줄과 개수】).',
 '성벽 위 쇠 바구니에 타오르는 봉화': f'염증 · 열 전용 {B} — L13a s2(선천 방어에 덧붙는 염증 · 열 — 성 전체에 알리는 불) · L13b(비만세포 경비의 불붙은 성냥 = 히스타민 → 봉화). ⚠ Gemini 가 그린 불의 얼굴은 지웠다. ⚠ 【불을 끄는 소화기 · 소방 호스】(항산화)와 다르다 — 끄는 이가 없다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('흰 옷 경비', f'★ {B} 성 세계 L13a — 파리채를 치켜들고 벌써 달려드는 경비(호중구 · 빠름 · 비특이 — s4 의 선천 쪽) · 입 벌린 둥근 흰 덩이(대식세포 — 세균을 통째로 입 안 혀 위에. 반쯤 물린 세균은 「먹히는지 뱉는지」 애매했다 · 일치 검사 1 · 3 · 4 · 5회) · 흰 옷 궁수(NK) · 톨게이트 초소 창구 · 삼베 자루 창의 경비(TLR 을 지닌 선천 면역세포). 흰 옷은 모두 가슴에 붉은 리본 배지(자기).')
add('장난감 병정(작은 나무 인형 병사)', f'★ {B} L13a 내성 발코니의 병정 둘 = 적응 방어의 T 세포(조끼 단추 넷씩 두 줄 = 세포독성 · 한 줄 넷 = 조력) · 문간의 잠옷 병정 = 적응 면역의 느림 · 특이 · 기억. 모두 검은 털모자 · 맨손(투구 · 칼 · 창 없음) · 가슴에 붉은 리본 배지.')
add('장난감 벌(노란 벌)', f'★ {B} L13a s3 내성 발코니의 태엽 벌이 든 황토빛 깃발 = 항체(옛 s13p01 · p02 의 깃발 문법) — 적응 방어 셋(세포독성 T · 조력 T · 항체)의 하나. 등의 태엽 손잡이는 장난감 표지(병정과 같은 장난감) — 【X 자 갈림길 팻말에서 나온 손이 감는 시계 태엽】(SCN)과 다르다(시계 · 감는 손 없음).')
add('조끼 단추의 줄과 개수', f'★ {B} L13a s3 발코니의 장난감 병정 둘 — 넷씩 두 줄(여덟) = 세포독성 T(CD8) · 한 줄 넷 = 조력 T(CD4). Gemini 에게는 민짜 조끼를 그리게 하고 단추는 PIL 이 찍었다. 같은 그림의 인터폰 판 단추 열여섯 · 잠옷 앞섶 단추 셋은 지웠다(독자가 「한 줄 넷쯤」으로 셌다 — 일치 검사 2회).')
add('웃는 초록 알약 세균(얼굴 · 팔다리)', f'★ {B} L13a — 화난 얼굴로 성벽 틈을 넘어 마당에 든 초록 알약(물결 꼬리 하나 = 편모 · 배지 없음) = 침입한 병원 세균(비자기). 하나는 금빛 꼰 밧줄 토막(DNA)을 쥐고 끈다.')
add('금빛 왕관 / 노란 깃발 / 유난히 작은 배', f'★ {B} L13a 장난감 벌이 든 황토빛 깃발 = 항체(성 세계) — 배에 단 노란 깃발(플라비)과 「누가 들었나(벌 · 손에) · 빛깔(황토)」로 가른다.')
add('꽃 도장', f'★ {B} L13a s6 수배 전단의 「금지 표지로 지운 분홍 꽃」 = 메틸기가 없다(비메틸화 CpG DNA — 세균 · 바이러스의 DNA). 꽃 = 메틸 그대로.')
add('DNA 의 세계별 물건 — 금빛 꼰 밧줄 · 지퍼와 나무 판자 · 금빛 짚끈 · 꼬인 나무 사다리', f'★ {B} 성 세계(L13)의 DNA = 금빛 꼰 밧줄 토막(L01 항구의 밧줄과 같은 꼴) — 초록 세균이 쥐고 끌고 · 수배 전단에도 그렸다.')
add('로마 병정 투구 + 칼', f'★ {B} 성 세계 L13 의 병사는 모두 장난감 병정(검은 털모자 · 맨손)과 흰 옷 경비다 — 투구 · 칼 · 창 · 방패 없음(조각 프롬프트마다 「No swords, spears, shields, helmets or armor」).')
add('주둥이를 밧줄로 묶은 자루 모양 집 · 창 안의 포자', f'★ {B} L13a s7 창 안에 흰 옷 경비가 앉은 삼베 자루 = 소낭 TLR — 창 안의 것(둥근 포자 / 사람)과 자리(곰팡이 마을 / 성 안뜰)로 가른다. 둘 다 낭(囊 · 주머니).')
add('사람이 멘 자루 개수', f'★ {B} L13a 땅에 선 사람 키만 한 삼베 자루(창 안에 경비) = 소낭 TLR — 사람이 멘 자루가 아니다.')
